//! Coefficient expressions as bytecode (generated by `model/rustgen.py`).
//!
//! Each `Expr` is a postfix program over the parameter values and its
//! program's constant pool: `CONST k` and `PARAM i` push, the others pop
//! their operands and push the result. The operations and their order are
//! exactly the expression tree's (rustgen emits it depth first, left
//! operand first), and each calls the same `math` function a compiled
//! expression did, so the values are the same bit for bit; one evaluator
//! replaces a compiled function per expression (2-10 KB of code per type).

use crate::math;

pub const CONST: u8 = 0;
pub const PARAM: u8 = 1;
pub const ADD: u8 = 2;
pub const SUB: u8 = 3;
pub const MUL: u8 = 4;
pub const DIV: u8 = 5;
pub const POW: u8 = 6;
pub const MIN: u8 = 7;
pub const MAX: u8 = 8;
pub const EXP: u8 = 9;
pub const LOG: u8 = 10;
pub const SQRT: u8 = 11;
pub const SIN: u8 = 12;
pub const COS: u8 = 13;
pub const TAN: u8 = 14;
pub const FLOOR: u8 = 15;
pub const ABS: u8 = 16;
/// floor(x + 0.5)
pub const ROUND: u8 = 17;

/// The deepest an expression's stack may go (rustgen checks).
pub const STACK: usize = 16;

/// `code` evaluated with parameter values `p` and constants `consts`.
pub fn eval(code: &[u8], consts: &[f64], p: &[f64]) -> f64 {
    let mut st = [0.0f64; STACK];
    let mut sp = 0usize;
    let mut i = 0usize;
    while i < code.len() {
        let op = code[i];
        i += 1;
        if op <= PARAM {
            let k = code[i] as usize;
            i += 1;
            st[sp] = if op == CONST { consts[k] } else { p[k] };
            sp += 1;
        } else if op <= MAX {
            sp -= 1;
            let (a, b) = (st[sp - 1], st[sp]);
            st[sp - 1] = match op {
                ADD => a + b,
                SUB => a - b,
                MUL => a * b,
                DIV => a / b,
                POW => math::pow(a, b),
                MIN => math::min(a, b),
                _ => math::max(a, b),
            };
        } else {
            let a = st[sp - 1];
            st[sp - 1] = match op {
                EXP => math::exp(a),
                LOG => math::ln(a),
                SQRT => math::sqrt(a),
                SIN => math::sin(a),
                COS => math::cos(a),
                TAN => math::tan(a),
                FLOOR => math::floor(a),
                ABS => math::abs(a),
                _ => math::floor(a + 0.5),
            };
        }
    }
    st[0]
}

#[cfg(test)]
mod tests {
    use super::*;

    const C: [f64; 3] = [2.0, 0.5, -3.25];

    fn ev(code: &[u8], p: &[f64]) -> f64 {
        eval(code, &C, p)
    }

    #[test]
    fn push_and_binary_operations() {
        let p = [10.0, 4.0];
        assert_eq!(ev(&[CONST, 2], &p), -3.25);
        assert_eq!(ev(&[PARAM, 1], &p), 4.0);
        assert_eq!(ev(&[PARAM, 0, PARAM, 1, ADD], &p), 14.0);
        assert_eq!(ev(&[PARAM, 0, PARAM, 1, SUB], &p), 6.0);     // left minus right
        assert_eq!(ev(&[PARAM, 0, CONST, 1, MUL], &p), 5.0);
        assert_eq!(ev(&[PARAM, 1, PARAM, 0, DIV], &p), 0.4);
        assert_eq!(ev(&[PARAM, 1, CONST, 1, POW], &p), math::pow(4.0, 0.5));
        assert_eq!(ev(&[PARAM, 0, PARAM, 1, MIN], &p), 4.0);
        assert_eq!(ev(&[PARAM, 0, PARAM, 1, MAX], &p), 10.0);
    }

    #[test]
    fn unary_operations_call_the_math_functions() {
        let x = 0.7310585786300049;
        let p = [x, -x];
        for (op, f) in [(EXP, math::exp as fn(f64) -> f64), (LOG, math::ln), (SQRT, math::sqrt),
                        (SIN, math::sin), (COS, math::cos), (TAN, math::tan),
                        (FLOOR, math::floor)] {
            assert_eq!(ev(&[PARAM, 0, op], &p), f(x));
        }
        assert_eq!(ev(&[PARAM, 1, ABS], &p), x);
        assert_eq!(ev(&[CONST, 2, ROUND], &p), -3.0);
        assert_eq!(ev(&[CONST, 1, ROUND], &p), 1.0);
    }

    #[test]
    fn nested_expressions_keep_their_order() {
        // (p0 - 2) / (0.5 * p1) - -3.25: the left operand is pushed first
        let p = [9.0, 4.0];
        let code = [PARAM, 0, CONST, 0, SUB, CONST, 1, PARAM, 1, MUL, DIV, CONST, 2, SUB];
        assert_eq!(ev(&code, &p), (9.0 - 2.0) / (0.5 * 4.0) - -3.25);
    }
}
